```go
package main

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/mitchellh/mapstructure"
)

// Define a structure that represents a Go struct with fields.
type MyStruct struct {
	Field1 int `json:"field1"`
	Field2 string `json:"field2"`
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	// Parse the Go source file into a map
	var myMap map[string]interface{}
	err := json.Unmarshal([]byte(fmt.Sprintf("%s", open(sourceFile))), &myMap)
	if err != nil {
		panic(err)
	}

	// Unmarshal the JSON data into our custom Go type (MyStruct)
	var myStruct MyStruct
	mapstructure.Decode(myMap, &myStruct)

	// Generate the Avro schema based on the parsed struct
	schema := GenerateAvroSchema(&myStruct)
	fmt.Printf("Generated Avro Schema:\n%s\n", schema)
}

// Function to generate Avro schema from a struct
func GenerateAvroSchema(structType interface{}) string {
	typeString := fmt.Sprintf("type %T {\n", reflect.TypeOf(structType))
	jsonSchema := mapstringToStringJSONSchema(structType)
	return typeString + "   " + jsonSchema + "}\n"
}

// Helper function to convert map[string]interface{} to map[string]map[string]string
func mapstringToStringJSONSchema(data interface{}) string {
	dataMap := map[string]interface{}{}
	mapstructure.Decode(data, &dataMap)

	jsonSchema := "{\n"
	for key, value := range dataMap {
		jsonSchema += fmt.Sprintf("    \"%s\": %s,\n", key, jsonValueToAvro(value))
	}
	jsonSchema = jsonSchema[:len(jsonSchema)-2] // Remove trailing comma and newline
	jsonSchema += "}"
	return jsonSchema
}

// Helper function to convert a Go value to an Avro-compatible JSON representation
func jsonValueToAvro(v interface{}) string {
	switch v.(type) {
	case bool:
		return fmt.Sprintf("\"%t\"", v)
	case float64:
		return fmt.Sprintf("\"%.9f\"", v)
	case int:
		return fmt.Sprintf("\"%d\"", v)
	default:
		return fmt.Sprintf("\"%v\"", v)
	}
}

// Open returns the contents of a file as a byte slice.
func open(filename string) ([]byte, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	b, err := ioutil.ReadAll(file)
	if err != nil {
		return nil, err
	}

	return b, nil
}
```

### Explanation:

- **Parsing the Source File**: The program reads the specified Go source file using `os.Open`. It then decodes this content into a Go struct using `mapstructure`.

- **Generating the Avro Schema**: 
  - The `GenerateAvroSchema` function takes the Go struct as input and generates an Avro schema based on its properties.
  - For each field in the struct, it constructs an Avro schema entry.
  - It uses helper functions like `mapstringToStringJSONSchema` and `jsonValueToAvro` to format these entries properly.

- **Helper Functions**:
  - `mapstringToStringJSONSchema`: Converts a map[string]interface{} representing the struct's fields into a JSON schema

